import itertools
import collections

# Search for C4-free bipartite graph with 7 points, 10 lines, >= 28 edges.

def check_rows(matrix):
    """matrix: list of sets (columns). Check no two rows appear together in >= 2 columns."""
    rows = 7
    for r1 in range(rows):
        for r2 in range(r1+1, rows):
            count = 0
            for col in matrix:
                if r1 in col and r2 in col:
                    count += 1
                    if count >= 2:
                        return False
    return True

def search_linear_space():
    rows = 7
    cols = 10
    min_col_sum = 2
    target_ones = 28

    all_subsets = []
    for r in range(min_col_sum, rows+1):
        for subset in itertools.combinations(range(rows), r):
            all_subsets.append(set(subset))

    print(f"Total candidate columns: {len(all_subsets)}")

    best = []

    def backtrack(selected, remaining_ones):
        nonlocal best
        if len(selected) > len(best):
            best = selected[:]
            total_ones = sum(len(all_subsets[i]) for i in selected)
            print(f"Found {len(selected)} columns with {total_ones} ones")

        if len(selected) == cols:
            total_ones = sum(len(all_subsets[i]) for i in selected)
            if total_ones >= target_ones:
                return True
            return False

        max_possible = remaining_ones + (cols - len(selected)) * rows
        if max_possible < target_ones:
            return False

        start = 0 if not selected else max(selected) + 1
        candidates = list(range(start, len(all_subsets)))
        candidates.sort(key=lambda i: len(all_subsets[i]), reverse=True)

        for idx in candidates:
            s = all_subsets[idx]
            # Check column intersection
            ok = True
            for si in selected:
                if len(s & all_subsets[si]) > 1:
                    ok = False
                    break
            if not ok:
                continue

            new_selected = selected + [idx]
            if check_rows([all_subsets[i] for i in new_selected]):
                if backtrack(new_selected, remaining_ones + len(s)):
                    return True
        return False

    backtrack([], 0)

    if len(best) == cols:
        print("Success!")
        result = [all_subsets[i] for i in best]
        total = sum(len(s) for s in result)
        print(f"Total edges: {total}")
        return result
    else:
        print(f"Best found: {len(best)} columns")
        if best:
            result = [all_subsets[i] for i in best]
            total = sum(len(s) for s in result)
            print(f"Total edges: {total}")
            for i, s in enumerate(result):
                print(f"  Col {i}: {sorted(s)}")
        return None

result = search_linear_space()
